import { expect, test, uniqueName } from "../../fixtures";

// Scenario: Reject invalid vendor fields (Scenario Outline, VEN-02)
const examples = [
  { field: "name", value: "A" },
  { field: "category", value: "furniture" },
  { field: "contact_email", value: "not-an-email" },
] as const;

for (const { field, value } of examples) {
  test(
    `rejects vendor with invalid ${field} (${JSON.stringify(value)}) with validation_error`,
    { tag: "@VEN-02" },
    async ({ apiAs }) => {
      // Arrange: a valid vendor payload, overriding only the field under test
      const member = await apiAs("member");
      const payload: Record<string, unknown> = {
        name: uniqueName("VEN-02 Vendor"),
        category: "software",
        contact_email: "billing@ven02.test",
      };
      payload[field] = value;

      // Act
      const response = await member.post("/api/vendors", { data: payload });

      // Assert
      expect(response.status()).toBe(422);
      const body = await response.json();
      expect(body.error.code).toBe("validation_error");
      expect(JSON.stringify(body.error)).toContain(field);
    },
  );
}
